"""Least-recently-used (LRU) cache with O(1) get/put."""

from collections import OrderedDict


class LRUCache:
    """Fixed-capacity cache that evicts the least-recently-used entry.

    A "use" is any successful ``get`` or any ``put`` (insert or update);
    it marks the key as most-recently-used.
    """

    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be a positive integer")
        self.capacity = capacity
        self._data = OrderedDict()  # key -> value, oldest first

    def get(self, key):
        """Return the value for ``key``, or -1 if absent. A hit counts as a use."""
        if key not in self._data:
            return -1
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        """Insert or update ``key`` (counts as a use); evict LRU if over capacity."""
        if key in self._data:
            self._data[key] = value
            self._data.move_to_end(key)
        else:
            self._data[key] = value
            if len(self._data) > self.capacity:
                self._data.popitem(last=False)
